def solve(inputs: dict) -> float:
    def pick(keys):
        for k in keys:
            if k in inputs:
                return int(inputs[k])
        raise KeyError(keys[0])
    base = pick(('base', 'a', 'number', 'x'))
    exponent = pick(('exponent', 'exp', 'power', 'b', 'n'))
    modulus = pick(('modulus', 'mod', 'm', 'divisor'))
    return pow(base, exponent, modulus)

