def solve(inputs: dict) -> float:
    def pick(keys):
        for k in keys:
            if k in inputs:
                return int(inputs[k])
        raise KeyError(keys[0])
    n = pick(('people', 'n', 'count', 'number_of_people'))
    k = pick(('step', 'k', 'every', 'interval'))
    survivor = 0
    for size in range(2, n + 1):
        survivor = (survivor + k) % size
    return survivor + 1

